"""
    args.py - Argument parsing.
"""

from argparse import ArgumentParser
from locale import getlocale
from sys import exit

from i18n import argument_help_texts

# This banner was generated by AI
# ---------------------------------------------------------------------------
# Argument parsing
# ---------------------------------------------------------------------------

# Neither code nor documentation text of this function is generated by AI
def _add_argument(parser, language: str, param: str, action: str):
    """
        This function takes parser as argparse.ArgumentParser() class object and adds an argument to it.
        The action parameter is directly passed to the add_argument call.
        The help text is automatically looked up in the i18n.argument_help_texts dictionary by the language and the param parameter.
        The dictionary must have language keys directly in the first depth (e.g. en) and the parameter help text in the next depth,
        as a value for a key that is the parameter string.
    """
    parser.add_argument(param, action=action, help=argument_help_texts[language][param])

# This function was generated by AI and modified by me to use the _add_argument function instead of parser.add_argument.
# I wrote the documentation text on my own.
def parse_args():
    """
        This function builds the argument parser with all arguments of the ya_build_wrapper program.
    """
    parser = ArgumentParser()

    language = getlocale()[0]
    language = language[:2] if language else "en"

    if not language or language not in argument_help_texts:
        print("Unsupported language detected !")
        exit(-1)
    
    _add_argument(parser, language, "--ci", "store_true")
    _add_argument(parser, language, "--fail-if-build-failed", "store_true")
    _add_argument(parser, language, "--quiet", "store_true")
    _add_argument(parser, language, "--output-job-time-as-json", "store_true")
    _add_argument(parser, language, "--cfg-input", "store")
    _add_argument(parser, language, "--generate-example-config", "store_true")

    return parser.parse_args()

